import { createApp, ref } from 'vue';
import { z } from 'zod';
import _ from 'lodash';
registerVariableSchema(z.object({ counter: z.coerce.number().prefault(0) }).passthrough(), { type: 'chat' });
const counter = ref(_.get(getVariables(), 'counter', 0)), note = ref('尚未操作'), busy = ref(false);
eventOn('counter_changed', value => { counter.value = value; });
eventOn(tavern_events.MESSAGE_RECEIVED, () => { counter.value = _.get(getVariables(), 'counter', 0); });
createApp({
 setup() { return { counter, note, busy, async add() {
  if (busy.value) return; busy.value = true;
  try {
   updateVariablesWith(vars => ({ ...vars, counter: Number(_.get(vars, 'counter', 0)) + 1 }));
   await MimaAuthor.whenCommitted(); counter.value = getVariables().counter;
   await eventEmit('counter_changed', counter.value); note.value = '变量已保存，事件已结算';
  } catch (e) { note.value = e.message; } finally { busy.value = false; }
 } }; },
 template: '<section><h3>离线插件示例</h3><p>当前值：{{counter}}</p><button @click="add" :disabled="busy">加一并保存</button><p>{{note}}</p></section>'
}).mount('#mima-author-root');
